 ->where('currency', $currency->value)
 ->whereIn('status', ['active', 'pending'])
 ->count();
 $pendingWithdrawals = Withdrawal::query()
 ->where('currency', $currency->value)
 ->whereIn('status', ['pending', 'under_review', 'kyc_required'])
